import type { APIRoute } from 'astro';

// Many tools look for /sitemap.xml first. The real sitemap is generated by
// @astrojs/sitemap as sitemap-index.xml + sitemap-0.xml, so serve the same index here.
export const GET: APIRoute = ({ site }) => {
  const base = import.meta.env.BASE_URL.replace(/\/$/, '');
  const pages = new URL(`${base}/sitemap-0.xml`, site).href;
  const xml = `<?xml version="1.0" encoding="UTF-8"?><sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><sitemap><loc>${pages}</loc></sitemap></sitemapindex>`;
  return new Response(xml, { headers: { 'Content-Type': 'application/xml' } });
};
